const categories=["All",...new Set(herbs.map(h=>h.category))],grid=document.getElementById("herbGrid"),search=document.getElementById("search"),count=document.getElementById("count"),empty=document.getElementById("empty"),categoryBar=document.getElementById("categoryBar"),modal=document.getElementById("modal"),modalBody=document.getElementById("modalBody");let activeCategory="All";
categoryBar.innerHTML=categories.map(c=>`<button class="category ${c==="All"?"active":""}" data-cat="${c}">${c}</button>`).join("");categoryBar.querySelectorAll(".category").forEach(btn=>btn.addEventListener("click",()=>{activeCategory=btn.dataset.cat;categoryBar.querySelectorAll(".category").forEach(x=>x.classList.remove("active"));btn.classList.add("active");render()}));
function filtered(){const q=search.value.trim().toLowerCase();return herbs.filter(h=>(activeCategory==="All"||h.category===activeCategory)&&(!q||[h.name,h.scientific,h.local,h.category,h.summary,...h.uses].join(" ").toLowerCase().includes(q)))}
function render(){const items=filtered();grid.innerHTML=items.map(h=>{const i=herbs.indexOf(h);return `<article class="herb-card" data-index="${i}"><div class="herb-icon">${h.icon}</div><h3>${h.name}</h3><div class="scientific">${h.scientific}</div>${h.local?`<div class="local-name">${h.local}</div>`:""}<p>${h.summary}</p><div class="learn">View educational profile →</div></article>`}).join("");count.textContent=`${items.length} herb${items.length===1?"":"s"}`;empty.hidden=items.length!==0;grid.querySelectorAll(".herb-card").forEach(c=>c.addEventListener("click",()=>openHerb(+c.dataset.index)))}
function openHerb(i){const h=herbs[i];modalBody.innerHTML=`<div class="herb-icon">${h.icon}</div><h2>${h.name}</h2><p class="scientific">${h.scientific}</p>${h.local?`<p><strong>Local name(s):</strong> ${h.local}</p>`:""}<p><strong>Category:</strong> ${h.category}</p><p>${h.summary}</p><h3>Traditional / educational information</h3><ul>${h.uses.map(x=>`<li>${x}</li>`).join("")}</ul><h3>Safety</h3><p>${h.safety}</p><p class="modal-note"><strong>Important:</strong> This profile is educational. It is not a diagnosis or treatment recommendation.</p>`;modal.classList.add("show");modal.setAttribute("aria-hidden","false")}
function closeModal(){modal.classList.remove("show");modal.setAttribute("aria-hidden","true")}document.getElementById("close").addEventListener("click",closeModal);modal.addEventListener("click",e=>{if(e.target===modal)closeModal()});search.addEventListener("input",render);document.getElementById("menuBtn").addEventListener("click",()=>document.getElementById("nav").classList.toggle("open"));document.querySelectorAll("nav a").forEach(a=>a.addEventListener("click",()=>document.getElementById("nav").classList.remove("open")));render();
